@router.put("/webhooks/{webhook_id}")
def update_webhook_destination(
    webhook_id: str,
    payload: WebhookUpdateSchema,
    client: OAuthClient = Security(get_oauth_client, scopes=["webhooks:write"]),
    db: Session = Depends(get_db)
):
    hook = db.query(Webhook).filter(Webhook.id == webhook_id, Webhook.client_id == client.id).first()
    if not hook:
        raise HTTPException(status_code=404, detail="Webhook not found")
    hook.destination_url = str(payload.destination_url)
    db.commit()
    return {"status": "updated", "id": webhook_id}
